import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.CBux2OW7.js";const p=JSON.parse('{"title":"ScoutedArticle Model","description":"","frontmatter":{},"headers":[],"relativePath":"backend/models/scouted-article.md","filePath":"backend/models/scouted-article.md"}'),c={name:"backend/models/scouted-article.md"};function l(r,e,d,s,n,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="scoutedarticle-model" tabindex="-1">ScoutedArticle Model <a class="header-anchor" href="#scoutedarticle-model" aria-label="Permalink to &quot;ScoutedArticle Model&quot;">​</a></h1><p><code>app/Models/ScoutedArticle.php</code> represents the &quot;pre-ingestion&quot; phase of the TechyNews pipeline. It acts as a holding queue for raw RSS feeds and scraped links before they are synthesized by the AI.</p><h2 id="database-schema-columns" tabindex="-1">Database Schema &amp; Columns <a class="header-anchor" href="#database-schema-columns" aria-label="Permalink to &quot;Database Schema &amp; Columns&quot;">​</a></h2><ul><li><code>id</code> (Primary Key)</li><li><code>source_url</code> (String): The original URL of the news piece.</li><li><code>original_title</code> (String): Unmodified headline from the RSS feed.</li><li><code>raw_content</code> (LongText): The scraped text body or RSS summary.</li><li><code>source_name</code> (String): e.g., &quot;TechCrunch&quot;, &quot;The Verge&quot;.</li><li><code>is_processed</code> (Boolean): Flag indicating if Gemini has already consumed this row to generate a final <code>Article</code>.</li><li><code>relevance_score</code> (Integer): Optional AI-scored metric to prioritize important news.</li></ul><h2 id="workflow-context" tabindex="-1">Workflow Context <a class="header-anchor" href="#workflow-context" aria-label="Permalink to &quot;Workflow Context&quot;">​</a></h2><ol><li><code>NewsService</code> polls RSS feeds and bulk inserts rows into <code>scouted_articles</code> with <code>is_processed = false</code>.</li><li>A CRON job runs <code>NewsAgent</code> which selects the top 5 most relevant, unprocessed <code>ScoutedArticle</code> rows.</li><li>The Agent feeds this raw data to Gemini to write a new <code>Article</code>.</li><li>The Agent marks the used <code>ScoutedArticle</code> rows as <code>is_processed = true</code>.</li></ol><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to &quot;Relationships&quot;">​</a></h2><ul><li>None explicitly required, though it conceptually acts as the parent data for an <code>Article</code>.</li></ul>',8)])])}const m=o(c,[["render",l]]);export{p as __pageData,m as default};
